    'asterisk_settings.rtp_help_body' => 'Səsi (RTP) hansı port aralığının daşıdığını və Asterisk-in gözlənilməz mənbədən gələn səsi rədd edib-etmədiyini idarə edir. Bu fayl (<code>/etc/asterisk/rtp.conf</code>) artıq panel tərəfindən yaradılır; serverdə əl ilə edilən dəyişikliklər növbəti "Tətbiq et" zamanı itir.',
