    'trunks.connection_mode_help' => 'IP əsaslı: qarşı tərəf IP ünvanı ilə tanınır və onun kontaktı statik saxlanılır — eyni şəbəkədə sabit IP-si olan qarşı tərəf üçün tövsiyə olunan rejim. Daxil olan qeydiyyat: qarşı tərəf bizə SIP REGISTER göndərir və onun ünvanı həmin qeydiyyatdan öyrənilir. Bu rejim istifadəçi adı və şifrə tələb edir; qarşı tərəf həm qeydiyyatını, həm də zənglərini onlarla autentifikasiya edir.',
