    'sound_packs.help_title' => 'Asterisk səs paketləri',
    'sound_packs.help_body' => 'Asterisk-in rəsmi sistem bildirişlərini və gözləmə musiqisini <code>downloads.asterisk.org</code> ünvanından endirir və quraşdırır. Hər paket bir formatda bir dildir; Asterisk zəngin kodekinə uyğun formatı səsləndirir, əks halda transkod edir (G.722 üçün g722, operatorlar üçün ulaw/alaw).<br>- <strong>Core:</strong> sistem bildirişləri, rəqəmlər, səsli poçt. <strong>Extra:</strong> əlavə bildirişlər; əvvəlcə eyni dilin core paketi quraşdırılmalıdır.<br>- <strong>Gözləmə musiqisi (opsound):</strong> <code>/var/lib/asterisk/moh/opsound</code> qovluğuna quraşdırılır; səsləndirmək üçün Gözləmə musiqisi tabında <strong>opsound</strong> adlı MOH sinfi yaradın.<br>- <strong>Türkçe (AiPBX):</strong> AiPBX-in öz türkcə bildirişləri (GitHub buraxılışı, SHA256 ilə yoxlanılmış); standart dil türkcədir, ona görə onları silmək sistem bildirişlərini səssiz edir. Silmə yalnız paketin quraşdırdığı faylları silir.',
