    'system_update.help_title' => 'Yeniləmə necə işləyir?',
    'system_update.help_body' => 'Yeniləmə əvvəlcə verilənlər bazasının, parametrlərin və Asterisk konfiqurasiyasının ehtiyat nüsxəsini çıxarır, sonra yeni versiyanı quraşdırır və hər şeyin işlədiyini yoxlayır. Hər hansı xəta baş verərsə, avtomatik olaraq əvvəlki versiyaya qayıdır. Yeniləmə zamanı Asterisk yenidən başladılır: davam edən zənglər kəsilir, buna görə aktiv zənglər olduqda yeniləmə başlamır. Bunu serverdə də icra etmək olar: <code>sudo aipbx-update</code>',
