    'certificates.help_title' => 'Sertifikat bələdçisi',
    'certificates.help_body' => 'Portal (HTTPS), WebRTC TURNS və SIP-TLS/WSS bir sertifikatdan birgə istifadə edir; burada edilən dəyişikliklər Apache, coturn və Asterisk-ə birlikdə tətbiq olunur. <b>Let\'s Encrypt</b> pulsuzdur və özü yenilənir; domen bu serverə yönəlməli və 80-ci port internetdən əlçatan olmalıdır. Təşkilatınızın sertifikatı varsa, <b>onu yükləyin</b> (PEM və ya PFX); yüklənmiş sertifikatlar avtomatik yenilənmir, müddəti bitməmiş yenisini yükləyin. <b>Özü imzalanmış</b> sertifikatla brauzerlər xəbərdarlıq göstərir və TURNS brauzerlərdə işləmir: firewall arxasındakı WebRTC zənglərində səs olmaya bilər.',
