    'queue_reports.help_body' => 'Növbəyə daxil olan hər zəng bir dəfə sayılır. <b>Cavablandırılan</b>: agentə qoşulub. <b>İtirilən</b>: zəng edən gözləyərkən dəstəyi qoyub və ya növbənin vaxtı bitib. <b>Qısa imtina</b>: %d saniyə ərzində dəstəyi qoyub; xidmət səviyyəsinə daxil edilmir. <b>Xidmət səviyyəsi</b>: hədəf müddət ərzində cavablandırılan zənglərin qısa imtinalar xaric bütün zənglərə nisbəti. <b>ASA</b>: cavablandırılan zənglərin orta gözləmə müddəti. <b>AHT</b>: orta danışıq müddəti. <b>Cavab vermə dərəcəsi</b> (agent): növbə agentə zəng etdikdə onun nə qədər tez-tez cavab verdiyi. <b>Geri zəng</b>: itirilən zəng, nömrəsinə sonradan daxili nömrədən zəng edildikdə və ya həmin nömrə yenidən zəng edib cavablandırıldıqda həll olunmuş sayılır. Məlumatlar Asterisk-in növbə jurnalından götürülür; hesabatı PDF və ya Excel kimi endirmək olar.',
