    'ai_tts.help_body' => 'Bulud xidmətləri (Google, Amazon Polly, Azure, ElevenLabs, OpenAI) vasitəsilə mətni təbii nitqə çevirir. Nəticəni dinləyin, MP3 kimi endirin və ya bir kliklə <b>elan</b> kimi saxlayın: o, Asterisk formatına (8 kHz WAV) çevrilir və IVR-lər, daxil olan marşrutlar və vaxt şərtləri üçün Səslər &amp; Elanlar bölməsinə əlavə olunur (Tətbiq et-dən sonra qüvvəyə minir). <b>Bu xidmətlər ödənişlidir</b> və simvol başına hesablanır; hər sintez simvol sayı ilə birlikdə tarixçədə saxlanılır. Giriş açarları hər provayderin konsolundan alınır, şifrələnmiş şəkildə saxlanılır və səhifədə bir daha göstərilmir.',
    'ai_tts.tab_speak' => 'Sintez et',
    'ai_tts.tab_providers' => 'Provayderlər',
    'ai_tts.providers_text' => 'İstifadə etmək istədiyiniz xidmətlərin giriş məlumatlarını daxil edin. Gizli açarlar şifrələnmiş şəkildə saxlanılır; saxlanılmış açarı saxlamaq üçün sahəni boş buraxın.',
