    'ai_tts.provider_hint_google' => 'Google Cloud Console → APIs &amp; Services: "Cloud Text-to-Speech API"-ni aktivləşdirin; xidmət hesabının JSON açarından (IAM → Service Accounts → Keys → JSON) və ya API açarından istifadə edin. Sorğu başına %s simvola qədər; daha uzun mətnlər bölünür.',
    'ai_tts.provider_hint_polly' => 'AWS IAM-da yalnız "polly:SynthesizeSpeech" və "polly:DescribeVoices" icazələri olan istifadəçi üçün giriş açarı yaradın. Sorğu başına %s simvola qədər.',
    'ai_tts.provider_hint_azure' => 'Azure Portal-da "Speech" resursu yaradın; açar və region (məs. westeurope) onun "Keys and Endpoint" səhifəsindədir. Sorğu başına %s simvola qədər.',
    'ai_tts.provider_hint_elevenlabs' => 'ElevenLabs → Profile → API Keys. Səslər hesabınızın səs kitabxanasından gəlir və çoxdillidir. Sorğu başına %s simvola qədər.',
