    'push.help_layer0' => '<strong>Qat 0 (asılılıq yoxdur - defolt):</strong> daimi WSS bağlantısı, Android 15 ilə uyğun <code>specialUse</code> ön plan xidməti və onu bərpa edən Doze-a davamlı <code>AlarmManager</code> nəzarətçisi. Heç bir xarici xidmət lazım deyil; cihaz boş vəziyyətdə olduqda və ya ekran söndükdə belə zənglər gəlir.',
    'push.help_layer1' => '<strong>Qat 1 (istəyə bağlı - Google FCM):</strong> aqressiv batareya məhdudiyyətləri olan OEM cihazlarında (Xiaomi, Huawei...) və ya istifadəçi tətbiqi sürüşdürüb bağladıqda əlavə oyandırma zəmanəti. <em>Yalnız daxili nömrənin aktiv SIP qeydiyyatı olmadıqda işə düşür, buna görə qeydiyyatda olan daxili nömrələr heç bir gecikmə görmür.</em>',
