    'storage.help_body' => '<p>Söhbət qoşmaları, onların miniatürləri və qrup şəkilləri standart olaraq serverin diskində saxlanılır (<code>/var/lib/aipbx/chat_files</code>). S3 uyğun anbarla (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) onlar əvəzinə bucket-ə gedir və böyük fayllar PBX-dən kənarda qalır.</p><p>Yükləmələr yenə də söhbət xidməti üzərindən keçir, buna görə söhbətin fayllarını yalnız onun iştirakçıları aça bilər; bucket özəl qala bilər. Keçiddən əvvəl saxlanılmış fayllar siz onları köçürənə qədər diskdən verilməyə davam edir. Bucket parametrləri saxlanılmazdan əvvəl yoxlanılır.</p><p>Zəng yazıları, səsli poçt və fakslar lokal diskdə qalır.</p>',
