    'netsvc.help_body' => 'DHCP server provizyon serverinin ünvanını verdikdə (option 66) masaüstü telefonlar onu özləri tapır. DHCP və TFTP ayrı-ayrılıqda yandırılır. <strong>DHCP server</strong> söndürüldükdə öz DHCP serveriniz qalır: aşağıda sadalanan seçimləri orada təyin edin. Yandırıldıqda AiPBX bir interfeysdə və ya VLAN-da ünvanlar paylayır. <strong>TFTP server</strong> yüklədiyiniz boot fayllarını və proqram təminatını verir. Hər telefonun konfiqurasiyası (SIP parolu ilə) həmişə HTTPS üzərindən verilir, heç vaxt TFTP üzərindən deyil.',
